create extension if not exists pgcrypto;
create type public.staff_role as enum ('MANAGER','KITCHEN');
create type public.order_status as enum ('NEW','ACCEPTED','PREPARING','READY','SERVED','CANCELLED');
create type public.payment_status as enum ('PENDING','SUCCESS','FAILED');
create table public.restaurants (id uuid primary key default gen_random_uuid(), name text not null, gst_rate numeric(5,4) not null default .05, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text, preferred_language text not null default 'en' check (preferred_language in ('en','ta')), created_at timestamptz not null default now());
create table public.restaurant_staff (restaurant_id uuid references public.restaurants on delete cascade, user_id uuid references auth.users on delete cascade, role public.staff_role not null, primary key (restaurant_id,user_id));
create table public.tables (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants on delete cascade, table_number int not null check(table_number between 1 and 100), qr_token uuid not null default gen_random_uuid(), is_active boolean not null default true, current_order_id uuid, unique(restaurant_id,table_number));
create table public.categories (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants on delete cascade, name text not null, name_ta text not null default '', sort_order int not null default 0, is_active boolean not null default true);
create table public.menu_items (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants on delete cascade, category_id uuid not null references public.categories, name text not null, name_ta text not null, description text not null default '', description_ta text not null default '', price numeric(10,2) not null check(price>=0), image_url text, is_available boolean not null default true, is_featured boolean not null default false, is_special boolean not null default false, is_vegetarian boolean not null default false, preparation_time int not null default 15, stock_quantity int not null default 0 check(stock_quantity>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customization_groups (id uuid primary key default gen_random_uuid(), menu_item_id uuid not null references public.menu_items on delete cascade, name text not null, required boolean not null default false);
create table public.customization_options (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.customization_groups on delete cascade, name text not null, price_delta numeric(10,2) not null default 0);
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text unique not null, restaurant_id uuid not null references public.restaurants on delete cascade, table_id uuid not null references public.tables, customer_session_id uuid not null, request_id text unique not null, status public.order_status not null default 'NEW', subtotal numeric(10,2) not null check(subtotal>=0), tax numeric(10,2) not null check(tax>=0), total numeric(10,2) not null check(total>=0), payment_method text not null default 'CASH', payment_status public.payment_status not null default 'PENDING', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders on delete cascade, menu_item_id uuid not null references public.menu_items, item_name_snapshot text not null, price_snapshot numeric(10,2) not null, quantity int not null check(quantity>0), customizations jsonb not null default '[]');
create table public.feedback (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders on delete cascade, customer_session_id uuid not null, rating int not null check(rating between 1 and 5), comment text not null default '', created_at timestamptz not null default now());
create table public.favourites (customer_id uuid not null references auth.users on delete cascade, menu_item_id uuid not null references public.menu_items on delete cascade, primary key(customer_id,menu_item_id));
create index orders_restaurant_status_created_idx on public.orders(restaurant_id,status,created_at desc);
create index menu_available_idx on public.menu_items(restaurant_id,is_available);
create index order_items_order_idx on public.order_items(order_id);
alter table public.restaurants enable row level security; alter table public.profiles enable row level security; alter table public.restaurant_staff enable row level security; alter table public.tables enable row level security; alter table public.categories enable row level security; alter table public.menu_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.feedback enable row level security; alter table public.favourites enable row level security;
create or replace function public.is_staff(target_restaurant uuid, target_role public.staff_role default null) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.restaurant_staff where restaurant_id=target_restaurant and user_id=auth.uid() and (target_role is null or role=target_role)); $$;
create policy public_menu_read on public.menu_items for select using (is_available=true and stock_quantity>0);
create policy staff_menu_manage on public.menu_items for all using (public.is_staff(restaurant_id,'MANAGER')) with check (public.is_staff(restaurant_id,'MANAGER'));
create policy staff_orders_read on public.orders for select using (public.is_staff(restaurant_id));
create policy staff_order_items_read on public.order_items for select using (exists(select 1 from public.orders o where o.id=order_id and public.is_staff(o.restaurant_id)));
create policy kitchen_order_update on public.orders for update using (public.is_staff(restaurant_id,'KITCHEN') or public.is_staff(restaurant_id,'MANAGER')) with check (public.is_staff(restaurant_id,'KITCHEN') or public.is_staff(restaurant_id,'MANAGER'));
create policy customer_feedback_insert on public.feedback for insert with check (true);
alter publication supabase_realtime add table public.orders, public.menu_items, public.feedback;
